function drawMap(){rect(0,0,800,500,'#151c25');for(let y=0;y<12;y++)for(let x=0;x<20;x++)drawTile(x,y,terrain(x,y));
 rect(66,257,40,25,'#4a4b47');rect(70,248,32,12,'#777569');rect(76,253,20,18,'#24323a');rect(82,257,8,14,'#738477');
 rect(591,126,18,30,'#686d6b');rect(595,119,10,9,'#aaa38b');rect(597,129,6,12,'#b8a365');
 for(let i=0;i<14;i++){let x=120+(i*83)%610,y=65+(i*47)%350;if(terrain(Math.floor(x/40),Math.floor(y/40))==='grass')rect(x,y,3,3,i%2?'#e4b077':'#d99d9b')}
 drawPerson(player.x*T+20,player.y*T+26,'#d7a752',player.face,1.1);
 rect(0,480,800,20,'#1a1b20');ctx.fillStyle='#ddcea8';ctx.font='10px "DM Mono"';ctx.fillText('GREENWARD ROAD  ·  DAY '+(1+Math.floor(fights/2)),14,494);ctx.fillStyle='#9f997f';ctx.fillText('WASD / ARROWS TO TRAVEL',620,494);
}
function drawBattle(){let g=ctx.createLinearGradient(0,0,0,500);g.addColorStop(0,'#1a2636');g.addColorStop(.58,'#536374');g.addColorStop(.59,'#5d7354');g.addColorStop(1,'#344e3a');ctx.fillStyle=g;ctx.fillRect(0,0,800,500);
 for(let i=0;i<8;i++){let x=i*120-20,h=70+(i*37%55);rect(x,235-h,125,h,'#343f4d');rect(x+20,242-h,40,h-7,'#3c4c56');rect(x+52,245-h,48,h-10,'#414f59')}
 rect(0,300,800,180,'#59754f');for(let i=0;i<55;i++){let x=(i*67)%800,y=310+(i*41)%160;rect(x,y,3,2,i%3?'#718b5b':'#8c9762')}
 // party formation
 heroes.forEach((h,i)=>{let x=90+(i%2)*65,y=344+Math.floor(i/2)*63;if(h.hp>0)drawPerson(x,y,h.color,1,1.45)});
 enemies.forEach((e,i)=>{if(e.hp<=0)return;let x=500+(i%3)*78,y=332+Math.floor(i/3)*86;drawMonster(x,y,e,i)});
 // Nameplates / hp
 enemies.forEach((e,i)=>{if(e.hp<=0)return;let x=473+(i%3)*78,y=272+Math.floor(i/3)*86;ctx.fillStyle='#171821cc';ctx.fillRect(x,y,90,31);ctx.fillStyle='#f0e2c6';ctx.font='9px "DM Mono"';ctx.textAlign='center';ctx.fillText(e.name,x+45,y+12);ctx.fillStyle='#3d292b';ctx.fillRect(x+8,y+18,74,5);ctx.fillStyle='#d87563';ctx.fillRect(x+8,y+18,74*Math.max(0,e.hp/e.max),5)});ctx.textAlign='left';
 rect(0,480,800,20,'#191a20');ctx.fillStyle='#ead393';ctx.font='10px "DM Mono"';ctx.fillText(battleBoss?'GUARDIAN OF THE CRYSTAL':'A WILD ENCOUNTER',14,494);ctx.fillStyle='#c9c0a9';ctx.fillText('ROUND '+round,720,494);
}
function drawMonster(x,y,e,i){if(e.kind==='slime'){rect(x-19,y-5,38,25,'#272e37');rect(x-18,y-12,36,22,e.color);rect(x-11,y-20,22,10,e.color);rect(x-8,y-7,4,4,'#fff0c8');rect(x+5,y-7,4,4,'#fff0c8');rect(x-7,y-6,2,3,'#28303a');rect(x+6,y-6,2,3,'#28303a')}else if(e.kind==='wolf'){rect(x-24,y-10,45,19,e.color);rect(x+13,y-17,19,17,e.color);rect(x+19,y-24,8,10,e.color);rect(x+24,y-11,13,5,'#c69b80');rect(x-20,y+4,7,12,'#493c34');rect(x+8,y+4,7,12,'#493c34');rect(x+26,y-11,3,3,'#f8df95')}else{rect(x-24,y-20,48,39,'#222630');rect(x-20,y-25,40,33,e.color);rect(x-10,y-35,20,16,e.color);rect(x-14,y-34,6,14,'#e7d29d');rect(x+8,y-34,6,14,'#e7d29d');rect(x-11,y-16,5,4,'#ffe9a0');rect(x+7,y-16,5,4,'#ffe9a0')};if(i===0&&state==='battle'&&active>=0){/* glow intentionally subtle */}}
function draw(){if(!ctx)return;ctx.imageSmoothingEnabled=false;if(state==='battle')drawBattle();else drawMap()}
function beginGame(){state='map';saved=true;$('#intro').classList.add('hidden');say('The old arch marks the edge of home. <b>Walk the green road</b>—the wilds are restless.');updateUI();draw();}
$('#start').addEventListener('click',beginGame);
function movement(dx,dy){if(state!=='map')return;let nx=Math.max(1,Math.min(18,player.x+dx)),ny=Math.max(1,Math.min(10,player.y+dy));player.face=dx<0?-1:1;if(['tree','water','rock'].includes(terrain(nx,ny)))return;player.x=nx;player.y=ny;steps++;draw();if(steps%6===0){if(Math.random()<.48)startBattle(false);else showToast('The wind stirs in the grass…')}if(crystals<4&&fights>=3&&steps%5===0){startBattle(true)}}
function startBattle(boss){state='battle';battleBoss=boss;round=1;active=-1;selectedSpell='';targetRow.classList.remove('visible');cmd.classList.add('visible');
 if(boss){const names=['Thorn Warden','Dune Colossus','Frost Drake','Ashen Knight'];enemies=[{name:names[crystals],kind:'boss',color:['#738a55','#c69b67','#79b6c0','#bb735c'][crystals],max:68+crystals*8,hp:68+crystals*8,atk:8+crystals*2,xp:28,gold:18}];say(`A crystal guardian emerges! <b>${names[crystals]}</b> blocks the way.`)}else{let sets=[[['Moss Slime','slime','#71b67c'],['Moss Slime','slime','#81c583']],[['Wildfang','wolf','#b28b6a'],['Moss Slime','slime','#71b67c']],[['Cave Imp','imp','#9b7bb1'],['Cave Imp','imp','#a883bd'],['Wildfang','wolf','#b28b6a']]];let set=sets[Math.floor(Math.random()*sets.length)];enemies=set.map(a=>({name:a[0],kind:a[1],color:a[2],max:18+fights*2,hp:18+fights*2,atk:4+Math.floor(fights/2),xp:7,gold:4})) ;say('<b>Monsters ambush the party!</b> Choose your actions carefully.')}
 turnQueue=[];queueIndex=0;updateUI();draw();startPlayerRound();}
function startPlayerRound(){round++;turnQueue=heroes.map((h,i)=>i).filter(i=>heroes[i].hp>0);queueIndex=0;nextHero();}
function nextHero(){while(queueIndex<turnQueue.length&&heroes[turnQueue[queueIndex]].hp<=0)queueIndex++;if(queueIndex>=turnQueue.length){enemyTurn();return}active=turnQueue[queueIndex];renderCommands();}
function renderCommands(){if(state!=='battle')return;const h=heroes[active];$('#commandlabel').textContent=h.name+' · '+h.job;$('#turnlabel').textContent=`${queueIndex+1} / ${turnQueue.length} · round ${round}`;row.innerHTML='';targetRow.innerHTML='';targetRow.classList.remove('visible');
 [['⚔ Attack','attack'],['✧ Magic','magic'],['✚ Potion','item'],['◈ Guard','guard']].forEach(([label,action])=>{let b=document.createElement('button');b.className='action';b.textContent=label;b.onclick=()=>chooseAction(action);row.append(b)});draw()}
function chooseAction(action){if(state!=='battle')return;if(action==='guard'){heroes[active].guard=true;finishHeroAction(`${heroes[active].name} braces for impact.`);return}if(action==='item'){if(!potions){showToast('No potions left!');return}showTargets('ally',i=>{potions--;heroes[i].hp=Math.min(heroes[i].max,heroes[i].hp+24);finishHeroAction(`${heroes[active].name} used a potion on ${heroes[i].name}.`);updateUI()});return}if(action==='magic'){const h=heroes[active];targetRow.innerHTML='';h.magic.forEach(sp=>{let b=document.createElement('button');b.className='action';b.textContent=sp==='Cure'?'Cure · 4 MP':sp==='Spark'?'Spark · 3 MP':'Flare · 6 MP';b.disabled=h.mp<(sp==='Cure'?4:sp==='Spark'?3:6);b.onclick=()=>chooseSpell(sp);targetRow.append(b)});targetRow.classList.add('visible');return}if(action==='attack'){showTargets('enemy',i=>{let h=heroes[active],e=enemies[i],dmg=Math.max(1,h.pow+rand(4)-2-Math.floor(e.atk/5));e.hp=Math.max(0,e.hp-dmg);floatingText(`${dmg}`,485+i*70,300,'#fff0a8');finishHeroAction(`${h.name} strikes ${e.name} for <b>${dmg}</b> damage.`);if(e.hp===0)showToast(e.name+' defeated!')})}}
function chooseSpell(sp){selectedSpell=sp;if(sp==='Cure'){showTargets('ally',i=>{let h=heroes[active];h.mp-=4;let amt=18+rand(8);heroes[i].hp=Math.min(heroes[i].max,heroes[i].hp+amt);finishHeroAction(`${h.name} casts Cure on ${heroes[i].name}. <b>${amt} HP restored.</b>`);updateUI()})}else{showTargets('enemy',i=>{let h=heroes[active],e=enemies[i],cost=sp==='Spark'?3:6;h.mp-=cost;let dmg=(sp==='Spark'?13:24)+rand(10);e.hp=Math.max(0,e.hp-dmg);finishHeroAction(`${h.name} casts ${sp}! <b>${dmg} damage.</b>`);updateUI()})}}
function showTargets(type,cb){targetRow.innerHTML='';let list=type==='ally'?heroes:enemies;list.forEach((x,i)=>{if(type==='enemy'&&x.hp<=0||type==='ally'&&x.hp<=0)return;let b=document.createElement('button');b.className='action';b.textContent=(type==='enemy'?'◆ ':'♥ ')+x.name;b.onclick=()=>cb(i);targetRow.append(b)});targetRow.classList.add('visible');$('#commandlabel').textContent=type==='enemy'?'Choose an enemy':'Choose an ally'}
function finishHeroAction(message){say(message);row.innerHTML='';targetRow.classList.remove('visible');updateUI();draw();if(enemies.every(e=>e.hp<=0)){winBattle();return}queueIndex++;setTimeout(nextHero,450)}
function enemyTurn(){if(state!=='battle')return;if(enemies.every(e=>e.hp<=0)){winBattle();return}$('#commandlabel').textContent='The monsters attack!';$('#turnlabel').textContent='Enemy turn';row.innerHTML='';targetRow.classList.remove('visible');let alive=enemies.filter(e=>e.hp>0);let ix=0;function hit(){if(state!=='battle')return;if(ix>=alive.length){heroes.forEach(h=>h.guard=false);round++;turnQueue=heroes.map((h,i)=>i).filter(i=>heroes[i].hp>0);queueIndex=0;nextHero();return}let e=alive[ix++],targets=heroes.map((h,i)=>({h,i})).filter(x=>x.h.hp>0);if(!targets.length){gameOver();return}let target=targets[rand(targets.length)],h=target.h;let dmg=Math.max(1,e.atk+rand(4)-Math.floor(h.def/2));if(h.guard){dmg=Math.ceil(dmg/2);h.guard=false}h.hp=Math.max(0,h.hp-dmg);say(`${e.name} hits ${h.name} for <b>${dmg}</b> damage.`);updateUI();draw();if(heroes.every(p=>p.hp<=0)){gameOver();return}setTimeout(hit,420)}hit()}
function winBattle(){if(state!=='battle')return;let xp=enemies.reduce((n,e)=>n+e.xp,0),loot=enemies.reduce((n,e)=>n+e.gold,0);gold+=loot;fights++;heroes.forEach(h=>{if(h.hp<=0)return;h.xp+=xp;while(h.xp>=h.next){h.xp-=h.next;h.lvl++;h.next+=18;h.max+=6;h.hp=Math.min(h.max,h.hp+14);h.maxmp+=2;h.mp=Math.min(h.maxmp,h.mp+2);h.pow+=2;h.def++}});
 if(battleBoss){crystals++;say(`<b>Crystal rekindled!</b> Its light flows into the party. ${crystals<4?'The wind points toward another guardian.':'The four crystals shine as one. The realm is saved!'}`);heroes.forEach(h=>{h.hp=Math.min(h.max,h.hp+18);h.mp=Math.min(h.maxmp,h.mp+5)})}else say(`<b>Victory!</b> The party earns ${xp} XP and ${loot} ◈.`);
 state='map';cmd.classList.remove('visible');active=-1;steps=0;updateUI();draw();showToast(battleBoss?'CRYSTAL REKINDLED!':'VICTORY!');if(crystals===4)$('#objective').innerHTML='<strong>✦ &nbsp;The realm restored</strong>All four crystals shine again. You are the Lightbearers!';}
function gameOver(){state='over';row.innerHTML='';targetRow.classList.remove('visible');$('#commandlabel').textContent='The light fades';$('#turnlabel').textContent='';say('The party has fallen. The road is still waiting.');$('#intro').classList.remove('hidden');$('.titlecard h1').innerHTML='THE END';$('.titlecard .subtitle').textContent='Even heroes need another try';$('.titlecard p').textContent='The crystals are still out there. Rise, Lightbearers, and try again.';$('#start').textContent='Try again  ▶';$('#start').onclick=()=>{heroes.forEach(h=>{h.hp=h.max;h.mp=h.maxmp});crystals=0;fights=0;gold=35;potions=3;state='map';$('#intro').classList.add('hidden');updateUI();draw()};updateUI()}
function rand(n){return Math.floor(Math.random()*n)}

